(789, '_transient_stackable_block_style_inheritance_css', '/* Block style inheritance */\n:root{--stk-button-column-gap:16px;--stk-button-row-gap:16px;--stk-container-color:var(--wp--preset--color--contrast);--stk-text-color:var(--wp--preset--color--contrast);--stk-default-text-color:var(--wp--preset--color--contrast);--stk-subtitle-color:var(--wp--preset--color--contrast);--stk-default-subtitle-color:var(--wp--preset--color--contrast);--stk-default-heading-color:var(--wp--preset--color--contrast);--stk-default-link-color:currentColor;--stk-button-padding:1rem 2.25rem 1rem 2.25rem;--stk-button-text-color:var(--wp--preset--color--base);--stk-default-button-text-color:var(--wp--preset--color--base);--stk-button-background-color:var(--wp--preset--color--contrast);--stk-default-button-background-color:var(--wp--preset--color--contrast);}:where(.stk-block-button, .stk-block-icon-button, .stk-block-pagination):not(.is-style-link) .stk-button{font-size:var(--wp--preset--font-size--medium);}:where(.stk-block-button, .stk-block-icon-button, .stk-block-pagination):not(.is-style-link) .stk-button:hover{border-color:transparent;}:where(.stk-block-button, .stk-block-pagination):not(.is-style-link, .is-style-ghost, .is-style-plain) > .stk-button{color:var(--wp--preset--color--base);}:where(.stk-block-button, .stk-block-pagination):not(.is-style-link, .is-style-ghost, .is-style-plain) > .stk-button:hover{color:var(--wp--preset--color--base);--stk-button-text-color:var(--wp--preset--color--base);--stk-default-button-text-color:var(--wp--preset--color--base);--stk-button-background-color:color-mix(in srgb, var(--wp--preset--color--contrast) 85%, transparent);--stk-default-button-background-color:color-mix(in srgb, var(--wp--preset--color--contrast) 85%, transparent);}:where(.stk-block-button, .stk-block-pagination).is-style-ghost > .stk-button{border-color:currentColor;--stk-button-ghost-border-width:1px;--stk-button-padding:calc(1rem - 1px) calc(2.25rem - 1px) calc(1rem - 1px) calc(2.25rem - 1px);}:where(.stk-block-heading) > :is(h1,h2,h3,h4,h5,h6){font-weight:400;line-height:1.125;letter-spacing:-0.1px;}:where(.stk-block-heading) > h1{font-size:var(--wp--preset--font-size--xx-large);}:where(.stk-block-heading) > h2{font-size:var(--wp--preset--font-size--x-large);}:where(.stk-block-heading) > h3{font-size:var(--wp--preset--font-size--large);}:where(.stk-block-heading) > h4{font-size:var(--wp--preset--font-size--medium);}:where(.stk-block-heading) > h5{font-size:var(--wp--preset--font-size--small);letter-spacing:0.5px;}:where(.stk-block-heading) > h6{font-size:var(--wp--preset--font-size--small);font-weight:700;text-transform:uppercase;letter-spacing:1.4px;}:where(.stk-block-heading__text, .stk-block-text__text, .stk-block-table-of-contents__link-wrapper, .stk-block-subtitle__text, .is-style-link) a{color:currentColor;}', 'off'),
